55	const PROCESSING_FEE = 5;
56	
57	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	};
64	
65	const basePremiumForItems = (items: Item[]): number =>
66	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
67	
68	const withInitialAssessmentSurcharge = (basePremium: number): number =>
69	  basePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
70	
71	const quotePremium = (items: Item[]): number =>
72	  Math.round(
73	    withInitialAssessmentSurcharge(basePremiumForItems(items)) + PROCESSING_FEE,
74	  );
75	
76	export const runScenario = (scenario: Scenario): ScenarioResult => {
77	  const quote = scenario.steps[0] as QuoteStep;
78	  return { results: [{ premium: quotePremium(quote.items) }] };
79	};
